# ── ألوان الأزرار من عمود D في الشيت ──────────────────
# القيم المقبولة: danger (أحمر)، success (أخضر)، primary (أزرق)، فارغ (افتراضي)
BUTTON_STYLES: dict[str, str] = {}
_VALID_STYLES = {"danger", "success", "primary"}

def _read_bot_texts_sheet():
    """يقرأ صفحة bot_texts: مفتاح | عربي | إنجليزي (بدون لون أو مواضع)."""
    bilingual = {}
    try:
        rows = bot_texts_sheet.get_all_values()
    except Exception as e:
        logger.warning(f"bot_texts sheet error: {e}")
        return bilingual
    for row in rows:
        if not row or not row[0].strip():
            continue
        key     = row[0].strip()
        ar_text = row[1].strip() if len(row) > 1 else ""
        en_text = row[2].strip() if len(row) > 2 else ""
        if not ar_text and not en_text:
            continue  # صف عنوان قسم أو ملاحظة، لا قيمة فعلية
        bilingual[key] = (ar_text, en_text)
    return bilingual

def _read_buttons_sheet(ws, with_positions=True):
    """
    يقرأ صفحة أزرار (keyboard_buttons أو inline_buttons):
      A=مفتاح B=عربي C=إنجليزي D=لون E=موضع_مستخدم F=موضع_أدمن G=موضع_مالك H=البطاقة
    يرجع: (bilingual, styles, positions, cards)
    """
    bilingual = {}
    styles    = {}
    positions = {}
    cards     = {}
    try:
        rows = ws.get_all_values()
    except Exception as e:
        logger.warning(f"buttons sheet error: {e}")
        return bilingual, styles, positions, cards
    for row in rows:
        if not row or not row[0].strip():
            continue
        key     = row[0].strip()
        ar_text = row[1].strip() if len(row) > 1 else ""
        en_text = row[2].strip() if len(row) > 2 else ""
        if not ar_text and not en_text:
            continue  # صف عنوان قسم أو ملاحظة
        style   = row[3].strip().lower() if len(row) > 3 else ""
        bilingual[key] = (ar_text, en_text)
        if style in _VALID_STYLES:
            styles[key] = style
        card = row[7].strip() if len(row) > 7 else ""
        if card:
            cards[key] = card
        if with_positions:
            pos_u = row[4].strip().upper() if len(row) > 4 else ""
            pos_a = row[5].strip().upper() if len(row) > 5 else ""
            pos_o = row[6].strip().upper() if len(row) > 6 else ""
            if pos_u or pos_a or pos_o:
                positions[key] = {"user": pos_u, "admin": pos_a, "owner": pos_o}
    return bilingual, styles, positions, cards

def load_bot_texts():
    """
    يقرأ كل نصوص وأزرار البوت من 3 صفحات منفصلة:
      - bot_texts:        مفتاح | عربي | إنجليزي                              (نصوص عادية، بدون لون/مواضع)
      - keyboard_buttons:  مفتاح | عربي | إنجليزي | لون | موضع_م | موضع_أ | موضع_و  (أزرار الكيبورد)
      - inline_buttons:    مفتاح | عربي | إنجليزي | لون | موضع_م | موضع_أ | موضع_و  (أزرار Inline)

    المواضع (E/F/G) تُستخدم فعلياً فقط من keyboard_buttons لبناء كيبورد القائمة الرئيسية.
    مواضع inline_buttons تُقرأ احتياطاً لكنها غير مستخدمة حالياً (الأزرار inline ترتيبها ثابت بالكود).
    """
    global BOT_TEXTS, BUTTON_STYLES, BUTTON_POSITIONS, _keyboards_cache, _allowed_texts_cache
    try:
        # تصفير BOT_TEXTS للافتراضي قبل كل قراءة — يمنع بقاء نص قديم محذوف من الشيت عالقاً
        # بالذاكرة بعد /refresh_texts (كان يبقى للأبد إلا بإعادة تشغيل البوت كاملاً)
        BOT_TEXTS = dict(DEFAULT_BOT_TEXTS)

        merged_bilingual = {}
        merged_styles    = {}

        # 1) نصوص عادية
        txt_bilingual = _read_bot_texts_sheet()
        merged_bilingual.update(txt_bilingual)

        # 2) أزرار الكيبورد (لها مواضع فعلية تُستخدم بالقائمة الرئيسية)
        kb_bilingual, kb_styles, kb_positions, kb_cards = _read_buttons_sheet(keyboard_buttons_sheet, with_positions=True)
        merged_bilingual.update(kb_bilingual)
        merged_styles.update(kb_styles)

        # 3) أزرار Inline (لها لون، مواضعها تُقرأ احتياطاً وغير مستخدمة حالياً)
        inl_bilingual, inl_styles, _inl_positions, _inl_cards = _read_buttons_sheet(inline_buttons_sheet, with_positions=True)
        merged_bilingual.update(inl_bilingual)
        merged_styles.update(inl_styles)

        # بناء BOT_TEXTS النهائي (مفتاح_ar / مفتاح_en) من كل المصادر مجتمعة
        for key, (ar_text, en_text) in merged_bilingual.items():
            BOT_TEXTS[f"{key}_ar"] = ar_text or DEFAULT_BOT_TEXTS.get(f"{key}_ar", key)
            BOT_TEXTS[f"{key}_en"] = en_text or DEFAULT_BOT_TEXTS.get(f"{key}_en", key)

        BUTTON_STYLES = merged_styles

        # فقط أزرار بطاقة "الرئيسية" تُستخدم لبناء كيبورد القائمة الرئيسية —
        # باقي البطاقات (اضافة_بيانات، تعديل_بيانات، بحث_بالتاريخ...) مبنية بدوال
        # منفصلة بالكود لا تعتمد على المواضع، فتضمينها هنا كان يسبب تصادم إحداثيات
        # (نفس الموضع A1 مثلاً) يخلط أزرار قوائم فرعية داخل القائمة الرئيسية.
        BUTTON_POSITIONS = {k: v for k, v in kb_positions.items() if kb_cards.get(k) == "الرئيسية"}

        # بناء الكيبوردات والنصوص المسموحة مرة واحدة في الذاكرة
        _build_keyboards_cache()

        n_pos = sum(1 for p in BUTTON_POSITIONS.values() if any(p.values()))
        logger.info(
            f"✅ نصوص محمّلة: {len(txt_bilingual)} نص عادي، "
            f"{len(kb_bilingual)} زر كيبورد، {len(inl_bilingual)} زر inline، "
            f"{len(merged_styles)} لون، {n_pos} موضع قائمة رئيسية"
        )
    except Exception as e:
        logger.warning(f"load_bot_texts error: {e}")

# ─── Cache الكيبوردات والنصوص المسموحة ───────────────
# يُبنى مرة عند load_bot_texts — لا يُعاد إلا بـ refresh_texts من بوت اللوج
BUTTON_POSITIONS: dict = {}   # {key: {"user": "A1", "admin": "", "owner": "A1"}}
_keyboards_cache: dict  = {}  # {"user": markup, "admin": markup, "owner": markup}
_allowed_texts_cache: dict = {}  # {"user": set(), "admin": set(), "owner": set()}

def _parse_pos(pos: str):
    """
    يحوّل 'A1' → (col=0, row=0) — العمود حرف، الصف رقم.
    A=0, B=1, C=2, ...
    الصف يبدأ من 1 في الشيت → نطرح 1 للـ index.
    """
    pos = pos.strip().upper()
    if not pos or len(pos) < 2:
        return None
    col_char = pos[0]
    row_str  = pos[1:]
    if not row_str.isdigit():
        return None
    col = ord(col_char) - ord('A')   # A=0, B=1...
    row = int(row_str) - 1           # 1→0, 2→1...
    return (row, col)

def _build_keyboards_cache():
    """
    يبني كيبورد لكل فئة من BUTTON_POSITIONS ويخزنه في _keyboards_cache.
    يبني أيضاً _allowed_texts_cache لكل فئة.
    يُستدعى فقط من load_bot_texts — لا تستدعه مباشرة.
    """
    global _keyboards_cache, _allowed_texts_cache

    roles = ["user", "admin", "owner"]
    # grid: {role: {(row,col): key}}
    grids = {r: {} for r in roles}

    for key, pos_dict in BUTTON_POSITIONS.items():
        for role in roles:
            pos = pos_dict.get(role, "")
            if not pos:
                continue
            parsed = _parse_pos(pos)
            if parsed is None:
                continue
            grids[role][parsed] = key

    new_kbs      = {}
    new_allowed  = {}

    for role in roles:
        grid = grids[role]
        if not grid:
            new_kbs[role]     = None
            new_allowed[role] = set()
            continue

        # ترتيب: صف تصاعدي، ثم عمود تصاعدي
        sorted_keys = sorted(grid.items(), key=lambda x: (x[0][0], x[0][1]))

        # تجميع حسب الصف
        rows_dict: dict = {}
        for (r, c), key in sorted_keys:
            rows_dict.setdefault(r, []).append((c, key))

        m = telebot.types.ReplyKeyboardMarkup(row_width=4, resize_keyboard=True)
        allowed = set()

        for r in sorted(rows_dict.keys()):
            row_btns = sorted(rows_dict[r], key=lambda x: x[0])
            buttons  = []
            for _, key in row_btns:
                btn_text = BOT_TEXTS.get(f"{key}_ar", key)
                allowed.add(btn_text)
                style = BUTTON_STYLES.get(key, "")
                if style in _VALID_STYLES:
                    try:
                        buttons.append(telebot.types.KeyboardButton(btn_text, style=style))
                    except:
                        buttons.append(telebot.types.KeyboardButton(btn_text))
                else:
                    buttons.append(telebot.types.KeyboardButton(btn_text))
            if buttons:
                m.row(*buttons)

        new_kbs[role]     = m
        new_allowed[role] = allowed

    _keyboards_cache     = new_kbs
    _allowed_texts_cache = new_allowed
    logger.info("✅ keyboards cache built")

def bt(key, uid=None):
    lang = "ar"
    if uid:
        load_user_lang(uid)
        lang = user_lang.get(uid, "ar")
    val = BOT_TEXTS.get(f"{key}_{lang}")
    if val:
        return val
    val_ar = BOT_TEXTS.get(f"{key}_ar")
    if val_ar:
        return val_ar
    return DEFAULT_BOT_TEXTS.get(f"{key}_ar") or key

def _make_btn(key, uid=None):
    """ينشئ KeyboardButton مع لون من الشيت إذا وُجد — يسقط بأمان إذا المكتبة لم تدعمه."""
    label = bt(key, uid)
    style = BUTTON_STYLES.get(key, "")
    if style in _VALID_STYLES:
        try:
            return telebot.types.KeyboardButton(label, style=style)
        except Exception:
            pass
    return telebot.types.KeyboardButton(label)

def _make_inline(key, label, callback_data):
    """ينشئ InlineKeyboardButton مع لون من الشيت إذا وُجد — يسقط بأمان إذا المكتبة لم تدعمه."""
    style = BUTTON_STYLES.get(key, "")
    if style in _VALID_STYLES:
        try:
            return telebot.types.InlineKeyboardButton(label, callback_data=callback_data, style=style)
        except Exception:
            pass
    return telebot.types.InlineKeyboardButton(label, callback_data=callback_data)

